<?php
declare(strict_types=1);
namespace HardnessMcp\Tools\Quote\Summary;
final class QuoteSummaryOutput
{
    public static function summary(array $summary): array{return ['quoted_total'=>(string)($summary['quoted_total']??'0'),'quote_count'=>(int)($summary['quote_count']??0)];}
    public static function rows(array $rows,string $groupBy): array
    { $result=[]; foreach($rows as $row){$base=['quoted_total'=>(string)($row['quoted_total']??'0'),'quote_count'=>(int)($row['quote_count']??0)]; if($groupBy==='day')$result[]=array_merge(['date'=>(string)$row['date']],$base); if($groupBy==='week')$result[]=array_merge(['week_start'=>(string)$row['week_start']],$base); if($groupBy==='month')$result[]=array_merge(['month'=>(string)$row['month']],$base); if($groupBy==='customer')$result[]=array_merge(['customer_id'=>$row['customer_id']===null?null:(int)$row['customer_id'],'customer_name'=>self::nullableString($row['customer_name']??null)],$base); if($groupBy==='document')$result[]=['document_id'=>(int)$row['document_id'],'issued_at'=>self::nullableString($row['issued_at']??null),'customer_name'=>self::nullableString($row['customer_name']??null),'customer_group_name'=>self::nullableString($row['customer_group_name']??null),'proposal_customer_name'=>self::nullableString($row['proposal_customer_name']??null),'status'=>(string)($row['status']??''),'status_label'=>self::statusLabel((string)($row['status']??'')),'quoted_total'=>(string)($row['quoted_total']??'0'),'quote_count'=>1]; if($groupBy==='seller_internal')$result[]=array_merge(['seller_internal_id'=>$row['seller_internal_id']===null?null:(int)$row['seller_internal_id'],'seller_internal_name'=>self::nullableString($row['seller_internal_name']??null),'supervisor_id'=>$row['supervisor_id']===null?null:(int)$row['supervisor_id'],'supervisor_name'=>self::nullableString($row['supervisor_name']??null)],$base); if($groupBy==='supervisor')$result[]=array_merge(['supervisor_id'=>$row['supervisor_id']===null?null:(int)$row['supervisor_id'],'supervisor_name'=>self::nullableString($row['supervisor_name']??null)],$base); if($groupBy==='status')$result[]=array_merge(['status'=>(string)$row['status'],'status_label'=>self::statusLabel((string)$row['status'])],$base);} return $result; }
    private static function statusLabel(string $status): string {return ['P'=>'Pendente','F'=>'Finalizado','C'=>'Cancelado','V'=>'Vencido','A'=>'Aprovado','N'=>'Negado','L'=>'Em análise'][$status]??$status;}
    private static function nullableString($value): ?string{return $value===null?null:(string)$value;}
}
